using Avalonia.Controls; using Avalonia.Interactivity; using Avalonia.Threading; using RafaoCluster.CrossPlatform.Models; using RafaoCluster.CrossPlatform.Services; using System.Diagnostics; using System.Net; using System.Net.Sockets;
namespace RafaoCluster.CrossPlatform;
public partial class MainWindow:Window
{
 private readonly ProcessRunner _runner=new(); private readonly PlatformService _platform; private readonly SettingsService _store; private ClusterSettings _settings=new(); private Process? _process; private bool _coordinator=true;
 public MainWindow(){InitializeComponent();_platform=new(_runner);_store=new(_platform.DataRoot);PlatformText.Text=_platform.PlatformName;Opened+=WindowOpened;Closing+=(_,_)=>Stop();}
 private async void WindowOpened(object? s,EventArgs e){_settings=await _store.LoadAsync();ApplyRole(_settings.Role!="Worker");CheckInstall();await Scan();}
 private void CoordinatorRole_Click(object? s,RoutedEventArgs e)=>ApplyRole(true); private void WorkerRole_Click(object? s,RoutedEventArgs e)=>ApplyRole(false);
 private void ApplyRole(bool c){_coordinator=c;CoordinatorRole.Classes.Set("secondary",!c);WorkerRole.Classes.Set("secondary",c);PageTitle.Text=c?"Configurar coordenador":"Configurar worker";PageSubtitle.Text=c?"Este computador organiza as GPUs e expõe a API local.":"Este computador empresta sua GPU ao coordenador.";PrimaryLabel.Text=c?"Workers (IP:porta, separados por vírgula)":"IP deste worker";SecondaryLabel.Text=c?"Modelo GGUF":"IP do coordenador";ThirdLabel.Text=c?"Porta da API":"Dispositivo";FourthLabel.Text=c?"Contexto":"Cache local";DownloadButton.IsVisible=c;StartButton.Content=c?"Iniciar coordenador":"Iniciar worker";PrimaryInput.Text=c?_settings.WorkerEndpoints:_settings.BindIp;SecondaryInput.Text=c?_settings.ModelPath:_settings.CoordinatorIp;ThirdInput.Text=c?_settings.ApiPort.ToString():_platform.IsMac?"Metal0":"CUDA0";FourthInput.Text=c?_settings.ContextSize.ToString():"Ativado";RpcPortInput.Text=_settings.RpcPort.ToString();CheckInstall();}
 private async void Scan_Click(object? s,RoutedEventArgs e)=>await Scan(); private async Task Scan(){HardwareSummary.Text="Detectando...";HardwareSummary.Text=await _platform.DiagnoseAsync();if(!_coordinator&&string.IsNullOrWhiteSpace(PrimaryInput.Text)){var ips=Dns.GetHostAddresses(Dns.GetHostName()).Where(x=>x.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(x));PrimaryInput.Text=ips.FirstOrDefault()?.ToString()??"";}}
 private void CheckInstall(){var installed=_coordinator?_platform.CoordinatorInstalled:_platform.WorkerInstalled;InstallStatus.Text=installed?(_coordinator?"● llama.cpp + RPC instalado":"● worker RPC instalado"):(_coordinator?"○ backend RPC não instalado":"○ worker RPC não instalado");}
 private async void Install_Click(object? s,RoutedEventArgs e){try{if(_process is{HasExited:false})throw new InvalidOperationException("Pare o coordenador/worker antes de atualizar o llama.cpp.");Log($"Instalando llama.cpp {PlatformService.CompatibleBuildTag} com suporte RPC...");await _platform.InstallAsync(Log);CheckInstall();Log($"Instalação concluída: {PlatformService.CompatibleBuildTag}.");}catch(Exception x){Log("ERRO: "+x.Message);}}
 private async void DownloadModel_Click(object? s,RoutedEventArgs e){var w=new ModelDownloadWindow(_platform.ModelsRoot);var ok=await w.ShowDialog<bool>(this);if(ok&&w.SelectedPath is not null){SecondaryInput.Text=w.SelectedPath;Log("Modelo selecionado: "+w.SelectedPath);}}
 private async void Start_Click(object? s,RoutedEventArgs e){try{if(_process is{HasExited:false})throw new InvalidOperationException("Já existe um processo ativo.");if(!int.TryParse(RpcPortInput.Text,out var rpc))throw new InvalidOperationException("Porta RPC inválida.");string exe;var args=new List<string>();if(_coordinator){if(!_platform.CoordinatorInstalled)throw new FileNotFoundException("Clique em Instalar / atualizar para preparar o llama.cpp com suporte RPC.");exe=_platform.Find("llama-server")!;if(!File.Exists(SecondaryInput.Text))throw new FileNotFoundException("Escolha ou baixe um GGUF.");if(!int.TryParse(ThirdInput.Text,out var api)||!int.TryParse(FourthInput.Text,out var ctx))throw new InvalidOperationException("Porta/contexto inválido.");var workers=(PrimaryInput.Text??"").Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);foreach(var w in workers)await TestWorker(w);args.AddRange(["--model",SecondaryInput.Text!,"--split-mode","layer","--n-gpu-layers","all","--fit","on","--ctx-size",ctx.ToString(),"--host","127.0.0.1","--port",api.ToString()]);if(workers.Length>0)args.AddRange(["--rpc",string.Join(',',workers)]);}else{if(!_platform.WorkerInstalled)throw new FileNotFoundException("Clique em Instalar / atualizar para preparar o worker RPC.");exe=_platform.Find("ggml-rpc-server")??_platform.Find("rpc-server")!;if(!IPAddress.TryParse(PrimaryInput.Text,out _))throw new InvalidOperationException("IP do worker inválido.");args.AddRange(["--host",PrimaryInput.Text!,"--port",rpc.ToString(),"--device",ThirdInput.Text??(_platform.IsMac?"Metal0":"CUDA0"),"--cache"]);}Log("Iniciando "+Path.GetFileName(exe));_process=_runner.Start(exe,args,Log);_process.Exited+=(_,_)=>Dispatcher.UIThread.Post(()=>{StartButton.IsEnabled=true;StopButton.IsEnabled=false;Log("Processo encerrado.");});StartButton.IsEnabled=false;StopButton.IsEnabled=true;await Save();}catch(Exception x){Log("ERRO: "+x.Message);}}
 private async Task TestWorker(string ep){var p=ep.Split(':');if(p.Length!=2||!int.TryParse(p[1],out var port))throw new InvalidOperationException("Worker inválido: "+ep);using var c=new TcpClient();await c.ConnectAsync(p[0],port).WaitAsync(TimeSpan.FromSeconds(3));Log("Worker respondeu: "+ep);}
 private void Stop_Click(object? s,RoutedEventArgs e)=>Stop(); private void Stop(){try{if(_process is{HasExited:false})_process.Kill(true);}catch{}StartButton.IsEnabled=true;StopButton.IsEnabled=false;}
 private async Task Save(){_settings.Role=_coordinator?"Coordinator":"Worker";_settings.RpcPort=int.TryParse(RpcPortInput.Text,out var r)?r:50052;if(_coordinator){_settings.WorkerEndpoints=PrimaryInput.Text??"";_settings.ModelPath=SecondaryInput.Text??"";_settings.ApiPort=int.TryParse(ThirdInput.Text,out var a)?a:8080;_settings.ContextSize=int.TryParse(FourthInput.Text,out var c)?c:4096;}else{_settings.BindIp=PrimaryInput.Text??"";_settings.CoordinatorIp=SecondaryInput.Text??"";}await _store.SaveAsync(_settings);}
 private void Log(string m)=>Dispatcher.UIThread.Post(()=>{LogBox.Text+=(LogBox.Text?.Length>0?"\n":"")+$"[{DateTime.Now:HH:mm:ss}] {m}";LogBox.CaretIndex=LogBox.Text?.Length??0;});
}
